  background: rgba(255, 255, 255, 0.3);
  transform: rotate(90deg);
}

.profileModalContent {
  padding: 25px;
  flex-grow: 1;
}

.profileModalFooter {
  padding: 20px 25px;
  border-top: 1px solid #eee;
  display: flex;
  justify-content: flex-end;
  gap: 15px;
